//
// Distance to a "glyphy" arc.
// The arc is described by two end points and height value from -1 to 1 (or a little shy from 1).
// At 0 the arc is a line and at 1 it is a 180 degree arc. Sign dictates which way the arc turns.  
//

// returns tan (2 * atan(d))
float tan2atan(const float d)
{
  return 2. * d / (1. - d * d);
}

float sdArc(const vec2 p, const vec2 p0, const vec2 p1, const float h)
{
    // center
    vec2 dir = p1 - p0;
    float d = tan2atan(h);
    vec2 c = mix(p0, p1, .5) + vec2(-dir.y, dir.x) / (2. * d);

    // radius
    float r = distance(p0, c);

    bool inStart = dot(p - p0, dir * mat2(1,  d, -d, 1)) >= 0.;
    bool inEnd = dot(p - p1, dir * mat2(1, -d,  d, 1)) <= 0.;
    bool inWedge = inStart && inEnd;

    return inWedge
        ? abs(distance(p, c) - r) // curve
        : min(distance(p, p0), distance(p, p1)); // endpoint
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // normalized pixel coordinates
    vec2 p = (2.0*fragCoord-iResolution.xy)/iResolution.y;
    vec2 m = (2.0*iMouse.xy-iResolution.xy)/iResolution.y;

    // animation
    float h = cos(iTime*0.8) * 0.99999;
	vec2 p0 = 0.8*cos( 0.43 *iTime + vec2(0.0,2.00) - 1.0 );
	vec2 p1 = 0.8*cos( 0.51 *iTime + vec2(0.0,1.50) + 1.0 );

    // distance
    float d = sdArc(p, p0, p1, h);

    // coloring
    vec3 col = (d>0.0) ? vec3(0.9,0.6,0.3) : vec3(0.5,0.85,1.0);
    col *= 1.0 - exp(-7.0*abs(d));
    col *= 0.8 + 0.2*cos(128.0*abs(d));
    col = mix( col, vec3(1.0), 1.0-smoothstep(0.0,0.015,abs(d)) );


    // End points
    col = mix(col, vec3(1.0,1.0,0.0), 1.0-smoothstep(0.0, 0.005, length(p-p0)-0.015));
    col = mix(col, vec3(1.0,1.0,0.0), 1.0-smoothstep(0.0, 0.005, length(p-p1)-0.015));


    // interactivity
    if( iMouse.z>0.001 )
    {
        d = sdArc(m, p0, p1, h);
        col = mix(col, vec3(1.0,1.0,0.0), 1.0-smoothstep(0.0, 0.005, abs(length(p-m)-abs(d))-0.0025));
        col = mix(col, vec3(1.0,1.0,0.0), 1.0-smoothstep(0.0, 0.005, length(p-m)-0.015));
    }

	fragColor = vec4(col, 1.0);
}
